def esc(s): return html.escape(s, quote=False)
def box(t): return '<span class="exam-box en">' + t + '</span>'
def exam(no, stem, body_html, given=None):
    g = box('<b>주어진 글</b> ' + esc(given)) if given else ''
    return '<b>' + str(no) + '. ' + stem + '</b>' + g + box(body_html)
def body(T): return ' '.join(esc(r[0]) for r in T)
def sec(t): return [['#', t, '']]
def rows(T): return [['', a, b] for a, b in T]
def L(T, i): return T[i][0]
BL = '<u>　　　　　　　　　　</u>'
def note(s): return '<br><small>' + s + '</small>'

