def q41():
    t = [esc(r[0]) for r in T41]
    rep = [(2, 'Examples of better', 'Examples of (a)<u>better</u>'), (3, "didn't care", "didn't (b)<u>care</u>"),
           (6, 'implies', '(c)<u>rejects</u>'), (11, 'a comfortable', 'a (d)<u>comfortable</u>'), (13, 'themselves accessible', 'themselves (e)<u>accessible</u>')]
    for i, a, b in rep:
        assert t[i].count(a) == 1, a
        t[i] = t[i].replace(a, b)
    return ' '.join(t[:10]) + '<br>' + ' '.join(t[10:]) + note('* shudder: 몸서리치다')
